const B_TAO_REPO = bash("#!/usr/bin/env bash\n# tao-repo.sh <gear-mini> <thư-mục-đích> — dựng repo \"gear\" có lịch sử 5 commit của 3 đồng nghiệp + remote origin.git\n# <gear-mini>: dự án sau lab 2.7 (lời giải mẫu). Giờ + tên tác giả cố định ⇒ mã băm commit trùng với bài nếu mã y hệt.\nset -euo pipefail\nSRC=$(cd \"${1:?thieu thu muc gear-mini}\" && pwd); D=${2:?thieu thu muc dich}\nexport GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1 TZ=Asia/Ho_Chi_Minh   # không dùng cấu hình/tên thật của máy bạn\nci() {  # ci <người> <ngày-giờ> <tham số git commit…>\n  local ai=$1 luc=$2 n e; shift 2\n  case $ai in an) n=\"An Nguyen\"; e=an.nv@labflow.dev;; binh) n=\"Binh Tran\"; e=binh.tt@labflow.dev;;\n              chi) n=\"Chi Le\"; e=chi.lh@labflow.dev;; *) n=\"SV OJT\"; e=sv.ojt@labflow.dev;; esac\n  GIT_AUTHOR_NAME=\"$n\" GIT_AUTHOR_EMAIL=$e GIT_COMMITTER_NAME=\"$n\" GIT_COMMITTER_EMAIL=$e \\\n  GIT_AUTHOR_DATE=\"$luc +0700\" GIT_COMMITTER_DATE=\"$luc +0700\" git commit -q \"$@\"\n}\nJ=src/main/java/com/labflow/gear/gear\n# thay <tệp> <chuỗi cũ> <chuỗi mới> — chạy giống nhau trên Linux, macOS, Git Bash (không phụ thuộc sed -i)\nthay() { python3 -c 'import sys;p,a,b=sys.argv[1:];s=open(p,newline=\"\").read();open(p,\"w\",newline=\"\").write(s.replace(a,b))' \"$@\"; }\n# tab <tệp…> 4 dấu cách đầu dòng ⇒ tab;  space <tệp…> ngược lại\ntab() { python3 -c 'import sys,re\nfor p in sys.argv[1:]:\n  s=open(p).read(); open(p,\"w\").write(re.sub(r\"(?m)^((?:    )+)\", lambda m: \"\\t\"*(len(m.group(1))//4), s))' \"$@\"; }\nspace() { python3 -c 'import sys,re\nfor p in sys.argv[1:]:\n  s=open(p).read(); open(p,\"w\").write(re.sub(r\"(?m)^(\\t+)\", lambda m: \"    \"*len(m.group(1)), s))' \"$@\"; }\ngrep -q 'who + \" da muon \" + dangMuon' \"$SRC/$J/GearService.java\" && grep -q 'chua duoc ai muon' \"$SRC/$J/GearService.java\" \\\n  || { echo \"Ma cua ban khac loi giai mau lab 2.7 — chep loi giai mau vao $SRC truoc.\"; exit 1; }\n[ -e \"$D\" ] && { echo \"$D da ton tai — chon thu muc moi (hoac tu xoa thu muc cu).\"; exit 1; }\nmkdir -p \"$D\"; cd \"$D\"\ngit init -q --bare -b main origin.git\ngit init -q -b main gear; cd gear\ncp -r \"$SRC\"/{pom.xml,mvnw,mvnw.cmd,.mvn,.gitattributes,src} .; rm -rf src/main/resources/static src/main/resources/templates\nrm -rf src/main/java/com/labflow/gear/gear/StartupLog.java\npython3 -c 'import sys;p=sys.argv[1];s=open(p,newline=\"\").read().replace(\"\\r\\n\",\"\\n\");open(p,\"w\",newline=\"\").write(s.replace(\"\\n\",\"\\r\\n\"))' mvnw.cmd\ncat > .gitignore <<'G'\ntarget/\n.env\n*.log\n# IntelliJ: chia sẻ cấu hình dự án, KHÔNG chia sẻ trạng thái cá nhân\n.idea/workspace.xml\n.idea/shelf/\n.idea/usage.statistics.xml\n.idea/dataSources.local.xml\n*.iws\nG\n# bản đầu: thụt tab (để commit \"style\" sau đổi sang 4 dấu cách)\ntab $(git ls-files -o --exclude-standard | grep '\\.java$')\n# commit 1 (An): khung dự án, chưa có hạn mức\npython3 - \"$J/GearService.java\" <<'P'\nimport sys,re; p=sys.argv[1]; s=open(p).read()\ns=s.replace('\\t\\trequireUnderLimit(who);\\n','')\ns=re.sub(r'\\tprivate void requireUnderLimit.*?\\n\\t}\\n\\n\\tprivate long countLoansOf.*?\\n\\t}\\n\\n','',s,flags=re.S)\nopen(p,'w').write(s)\nP\ngit add -A; ci an \"2026-11-02 09:00:00\" -m \"chore(GEAR-1): khoi tao gear-mini (Spring Boot 4.2)\"\n# commit 2 (Binh): thêm hạn mức mượn\ncp \"$SRC/$J/GearService.java\" \"$J/GearService.java\"\ntab \"$J/GearService.java\"\nthay \"$J/GearService.java\" '\" chua duoc ai muon\"' '\" chua ai muon\"'\ngit add -A; ci binh \"2026-11-05 14:20:00\" -m \"feat(GEAR-12): gioi han so mon moi nguoi duoc muon\"\n# commit 3 (Chi): sửa thông báo lỗi khi trả\nthay \"$J/GearService.java\" '\" chua ai muon\"' '\" chua duoc ai muon\"'\ngit add -A; ci chi \"2026-11-09 10:05:00\" -m \"fix(GEAR-19): thong bao ro khi tra mon chua ai muon\"\n# commit 4 (An): định dạng lại toàn bộ — tab ⇒ 4 dấu cách\nspace $(git ls-files '*.java')\ngit add -A; ci an \"2026-11-12 16:45:00\" -m \"style: dinh dang lai toan bo (tab -> 4 dau cach)\"\n# commit 5 (Binh): thêm cấu hình\nprintf 'spring.application.name=gear-mini\\ngear.max-loans=2\\nserver.port=41805\\n' > src/main/resources/application.properties\ngit add -A; ci binh \"2026-11-16 08:30:00\" -m \"chore(GEAR-21): dat cong 41805 cho moi truong dev\"\ngit remote add origin ../origin.git\ngit push -q origin main 2>/dev/null\ngit branch -u origin/main >/dev/null\ngit config user.name \"SV OJT\"; git config user.email sv.ojt@labflow.dev\n");
const B_PRE_COMMIT = bash("#!/bin/sh\n# .git/hooks/pre-commit — chặn commit có dòng debug hoặc khoá truy cập AWS trong phần đã stage\nloi=0\nif git diff --cached -U0 | grep -nE '^\\+.*System\\.out\\.println\\(\"DEBUG'; then\n  echo \"pre-commit: con dong DEBUG trong phan da stage — bo ra hoac dung logger\"; loi=1\nfi\nif git diff --cached -U0 | grep -nE '^\\+.*AKIA[0-9A-Z]{16}'; then\n  echo \"pre-commit: phat hien khoa truy cap AWS — KHONG commit bi mat\"; loi=1\nfi\nexit $loi\n");
