const B_CHUNG_LAB = bash("# chung-lab.sh — nạp bằng source trong các script lab 5.4 (môi trường git sạch + hàm ci/thay)\nexport GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1 TZ=Asia/Ho_Chi_Minh\nci() { local ai=$1 luc=$2 n e; shift 2\n  case $ai in an) n=\"An Nguyen\"; e=an.nv@labflow.dev;; binh) n=\"Binh Tran\"; e=binh.tt@labflow.dev;; *) n=\"SV OJT\"; e=sv.ojt@labflow.dev;; esac\n  GIT_AUTHOR_NAME=\"$n\" GIT_AUTHOR_EMAIL=$e GIT_COMMITTER_NAME=\"$n\" GIT_COMMITTER_EMAIL=$e \\\n  GIT_AUTHOR_DATE=\"$luc +0700\" GIT_COMMITTER_DATE=\"$luc +0700\" git commit -q \"$@\"; }\nthay() { python3 -c 'import sys;p,a,b=sys.argv[1:];s=open(p,newline=\"\").read()\nassert a in s, \"khong thay doan can sua trong \"+p\nopen(p,\"w\",newline=\"\").write(s.replace(a,b,1))' \"$@\"; }\nJ=src/main/java/com/labflow/gear/gear\n");
const B_PRE_RECEIVE = bash("#!/usr/bin/env bash\n# (giả lập GitLab) hook pre-receive của origin.git: bảo vệ main + luật commit của dự án gear\nz=0000000000000000000000000000000000000000; loi=0\nwhile read cu moi ref; do\n  [ \"$moi\" = $z ] && continue\n  if [ \"$ref\" = refs/heads/main ] && [ \"${GL_USER:-sv}\" != truong-nhom ]; then\n    echo \"(gia lap) GitLab: You are not allowed to push code to protected branches on this project.\"; loi=1; continue\n  fi\n  if [ \"$cu\" = $z ]; then ds=$(git rev-list \"$moi\" --not --branches); else ds=$(git rev-list \"$cu..$moi\"); fi\n  for c in $ds; do\n    msg=$(git log -1 --format=%s \"$c\"); np=$(git rev-list --parents -n1 \"$c\" | wc -w)\n    if [ \"$np\" -le 2 ] && ! [[ $msg =~ ^(feat|fix|chore|refactor|test|docs|style)\\(GEAR-[0-9]+\\):\\  ]]; then\n      echo \"(gia lap) tu choi ${c:0:7}: thong diep '$msg' sai mau 'loai(GEAR-n): ...'\"; loi=1; fi\n    for f in $(git diff-tree --no-commit-id --name-only -r --diff-filter=AM \"$c\"); do\n      case $f in .env|*/.env|.idea/workspace.xml) echo \"(gia lap) tu choi ${c:0:7}: commit tep ca nhan/bi mat $f\"; loi=1;; esac\n    done\n  done\ndone\nexit $loi\n");
const B_TAO_LAB54 = bash("#!/usr/bin/env bash\n# tao-lab54.sh <gear-mini> [thư-mục-lab] — dựng lab 5.4: origin.git (main được bảo vệ, giả lập GitLab) + bản clone \"gear\" sáng thứ Hai\nset -euo pipefail\nL=$(cd \"$(dirname \"$0\")\" && pwd); D=${2:-$HOME/ide-lab5}\n\"$L/tao-repo.sh\" \"${1:?thieu thu muc gear-mini}\" \"$D\" 2>&1 | grep -v \"LF will\" || true\nsource \"$L/chung-lab.sh\"\ncp \"$L/pre-receive\" \"$D/origin.git/hooks/pre-receive\"; chmod +x \"$D/origin.git/hooks/pre-receive\"\ncd \"$D/gear\"\nthay .gitignore $'.env\\n' ''                       # .gitignore của dự án quên .env — việc 2 của lab\ngit add .gitignore; ci an \"2026-11-20 09:00:00\" -m \"chore(GEAR-44): don .gitignore\"\nGL_USER=truong-nhom git push -q origin main\n# máy bạn sáng thứ Hai: .env thật, workspace.xml của IntelliJ, một dòng debug còn sót từ tuần trước\nprintf 'DB_URL=jdbc:postgresql://10.20.0.15:5432/gear\\nDB_PASSWORD=Gear@2026-dev\\n' > .env\nmkdir -p .idea\nprintf '<project version=\"4\"><component name=\"ChangeListManager\"/></project>\\n' > .idea/workspace.xml\nprintf '<project version=\"4\"><component name=\"ProjectRootManager\" project-jdk-name=\"21\"/></project>\\n' > .idea/misc.xml\nthay $J/GearService.java $'    public Gear returnGear(long id) {\\n        Gear g = findOrThrow(id);\\n' $'    public Gear returnGear(long id) {\\n        Gear g = findOrThrow(id);\\n        System.out.println(\"DEBUG return \" + g);\\n'\necho \"Lab 5.4 san sang: $D/gear\"; git status -s\n");
const B_DONG_NGHIEP = bash("#!/usr/bin/env bash\n# dong-nghiep.sh [thư-mục-lab] — Binh đẩy lên main một thay đổi sẽ đụng nhánh của bạn (bước 6 của lab)\nset -euo pipefail\nL=$(cd \"$(dirname \"$0\")\" && pwd); D=${1:-$HOME/ide-lab5}; source \"$L/chung-lab.sh\"\nT=$(mktemp -d); git clone -q \"$D/origin.git\" \"$T/b\"; cd \"$T/b\"\nthay $J/GearController.java '    @PostMapping(\"/{id}/borrow\")' $'    @GetMapping(\"/count\")\\n    public Map<String, Integer> count() {\\n        return Map.of(\"available\", service.available().size());\\n    }\\n\\n    @PostMapping(\"/{id}/borrow\")'\nthay $J/GearService.java $'    private Gear findOrThrow(long id) {\\n' $'    private Gear findOrThrow(long id) {\\n        if (id <= 0) {\\n            throw new IllegalArgumentException(\"id phai duong: \" + id);\\n        }\\n'\ngit add -A; ci binh \"2026-11-24 11:00:00\" -m \"feat(GEAR-46): them GET /count, chan id am\"\nGL_USER=truong-nhom git push -q origin main\ncd /; rm -rf \"$T\"; echo \"Binh da push GEAR-46 len main.\"\n");
const B_KIEM54 = bash("#!/usr/bin/env bash\n# kiem54.sh [thư-mục-lab] — chấm lab 5.4 trên chính origin.git (thứ cả nhóm thấy), không tin máy bạn\nset -uo pipefail\nL=$(cd \"$(dirname \"$0\")\" && pwd); D=${1:-$HOME/ide-lab5}; source \"$L/chung-lab.sh\"\nO=$D/origin.git; diem=0; tong=0\nok() { tong=$((tong+1)); if [ \"$1\" = 0 ]; then diem=$((diem+1)); echo \"  DAT   $2\"; else echo \"  CHUA  $2${3:+ — $3}\"; fi; }\ncd \"$O\"\nnh=$(git for-each-ref --format='%(refname:short)' 'refs/heads/feature/GEAR-45*' | head -1)\n[ -n \"$nh\" ]; ok $? \"1. co nhanh feature/GEAR-45-… tren origin\" \"chua push nhanh\"\n[ -z \"$nh\" ] && { echo \"Diem: $diem/$tong\"; exit 1; }\ngit merge-base --is-ancestor main \"$nh\"; ok $? \"2. nhanh da cap nhat main moi nhat (co GEAR-46 cua Binh)\" \"chua merge/rebase origin/main\"\nds=$(git rev-list --no-merges main..\"$nh\"); n=$(echo \"$ds\" | grep -c .)\n[ \"$n\" -ge 2 ] && [ \"$n\" -le 6 ]; ok $? \"3. 2–6 commit cua ban (khong tinh merge): $n\" \"nen chia nho hon/gop lai\"\nxau=\"\"; to=\"\"; for c in $ds; do\n  s=$(git log -1 --format=%s $c); [[ $s =~ ^(feat|fix|chore|refactor|test|docs)\\(GEAR-45\\):\\  ]] || xau=\"$xau ${c:0:7}\"\n  m=$(git show --numstat --format= $c | awk '{a+=$1+$2} END{print a+0}'); [ \"$m\" -le 60 ] || to=\"$to ${c:0:7}($m dong)\"; done\n[ -z \"$xau\" ]; ok $? \"4. moi thong diep dung mau loai(GEAR-45): …\" \"sai:$xau\"\n[ -z \"$to\" ]; ok $? \"5. moi commit <= 60 dong thay doi\" \"qua to:$to\"\nbad=$(for c in $(git rev-list main..\"$nh\"); do git diff-tree --no-commit-id --name-only -r $c; done | grep -E '(^|/)\\.env$|\\.idea/' | sort -u | tr '\\n' ' ')\n[ -z \"$bad\" ]; ok $? \"6. khong commit .env / .idea\" \"co: $bad\"\ngit show \"$nh:.gitignore\" | grep -qx '.env'; ok $? \"7. .gitignore co dong .env\"\n! git grep -qE 'System\\.out\\.println\\(\"DEBUG|^(<<<<<<<|=======|>>>>>>>)( |$)' \"$nh\" -- src; ok $? \"8. khong con dong DEBUG / dau xung dot o dau nhanh\" \"$(git grep -nE 'DEBUG|^<<<<<<<' \"$nh\" -- src | head -2 | tr '\\n' ' ')\"\ngit grep -q '@GetMapping(\"/{id}\")' \"$nh\" -- src/main && git grep -q 'GearNotFoundException' \"$nh\" -- src/test; ok $? \"9. co GET /api/gears/{id} va test 404\"\nT=$(mktemp -d); git archive \"$nh\" | tar -xm -C \"$T\"\n( cd \"$T\" && ${MVNW:-./mvnw} -q test > \"$T.log\" 2>&1 ); r=$?; ok $r \"10. ./mvnw test xanh tren ma o dau nhanh\" \"xem $T.log\"\nrm -rf \"$T\"; [ $r = 0 ] && rm -f \"$T.log\"\necho \"Diem: $diem/$tong\"; [ $diem = $tong ]\n");
